t3<-local({oi<-w%>%group_by(office_id)%>%summarise(firstoffice=min(year_num),.groups="drop");sf<-w%>%group_by(staff_id)%>%summarise(firstyear=min(year_num),.groups="drop");lag<-w%>%select(staff_id,year_num,lk=kyoku_group,lka=ka,lkg=ka_group_norm)%>%mutate(year_num=year_num+1);tr<-w%>%filter(year_num==1944)%>%left_join(oi,by="office_id")%>%left_join(sf,by="staff_id")%>%left_join(lag,by=c("staff_id","year_num"))%>%mutate(at=case_when(is.na(lk)|is.na(kyoku_group)~NA_character_,!is.na(ka_group_norm)&!is.na(lkg)&ka_group_norm==lkg~"same_section",(is.na(ka_group_norm)|is.na(lkg))&lk==kyoku_group&!is.na(lka)&!is.na(ka)&lka==ka~"same_section",lk==kyoku_group~"same_department",lk!=kyoku_group~"different_department"),nh=if_else(year_num==firstoffice,NA,year_num==firstyear));po<-tr%>%group_by(kyoku,ka,office_id,kakari,pos_norm)%>%summarise(total_internal=sum(at%in%c("same_section","same_department","different_department"),na.rm=TRUE),new_hires=sum(nh,na.rm=TRUE),.groups="drop");cm<-w%>%filter(year_num<1944,!is_female)%>%group_by(office_id,kakari,pos_norm)%>%summarise(cum=n_distinct(staff_id),.groups="drop");dr<-w%>%filter(year_num==1944,drafted%in%TRUE)%>%group_by(office_id,kakari,pos_norm)%>%summarise(D=sum(!is_female),.groups="drop");q<-po%>%left_join(cm,by=c("office_id","kakari","pos_norm"))%>%left_join(dr,by=c("office_id","kakari","pos_norm"))%>%mutate(across(c(cum,D),~replace_na(.x,0)),kaid=if_else(!is.na(ka)&!is.na(kyoku),paste(kyoku,ka),NA_character_))%>%filter(!is.na(kaid));write_csv(q,file.path(tab,"table3_consistency_panel_1944.csv"));map_dfr(c("total_internal","new_hires"),~{m<-tryCatch(feols(as.formula(paste0(.x,"~D+log1p(cum)|kaid+pos_norm")),q,cluster=~office_id),error=function(e)e);if(inherits(m,"error"))tibble(outcome=.x,estimate=NA_real_,se=NA_real_,error=conditionMessage(m))else tibble(outcome=.x,estimate=coef(m)["D"],se=se(m)["D"],error="")})})
