t3<-t3%>%left_join(pub,by=c("outcome"="model"))%>%mutate(same_sign=if_else(is.na(estimate),NA,sign(estimate)==sign(published_estimate)));write_csv(t3,file.path(tab,"table3_consistency_1944.csv"));if(any(!t3$same_sign,na.rm=TRUE))stop("STOP: Table 3 sign mismatch")

# Restricted-null six-point Webb score bootstrap.
webbp<-function(m,term,B=9999L){X<-m$X_demeaned;y<-m$y_demeaned;j<-match(term,colnames(X));if(is.na(j))return(NA_real_);X0<-X[,-j,drop=FALSE];u<-lm.fit(X0,y)$residuals;x<-lm.fit(X0,X[,j])$residuals;cl<-m$fixef_id$kyoku_fe;s<-rowsum(x*u,cl,reorder=FALSE)[,1];to<-coef(m)[term]/se(m,cluster=~kyoku_fe)[term];W<-c(-sqrt(1.5),-1,-sqrt(.5),sqrt(.5),1,sqrt(1.5));ww<-matrix(sample(W,B*length(s),TRUE),B);z<-sweep(ww,2,s,"*");tb<-rowSums(z)/sqrt(rowSums(z^2));(1+sum(abs(tb)>=abs(to),na.rm=TRUE))/(B+1)}
fit<-function(d,y,pools,fam,spec,type="ols"){logs<-paste0("log_",pools);ints<-paste0("Draft_ko:",logs);f<-as.formula(paste(y,"~",paste(c("Draft_ko",ints,"Draft_ko:logStaff",logs,"logStaff"),collapse="+"),"|kyoku_fe+pos_norm"));warn<-character();m<-tryCatch(withCallingHandlers(if(type=="ols")feols(f,d,demeaned=TRUE)else fepois(f,d),warning=function(x){warn<<-c(warn,conditionMessage(x));invokeRestart("muffleWarning")}),error=function(x)x);if(inherits(m,"error"))return(tibble(family=fam,outcome=y,spec,type,status="failed",diagnostic=conditionMessage(m)));a<-tryCatch(as.data.frame(coeftable(m,vcov=~kyoku_fe))%>%rownames_to_column("term"),error=function(x)NULL);if(is.null(a))return(tibble(family=fam,outcome=y,spec,type,status="failed",diagnostic="kyoku clustered covariance failed"));names(a)[2:5]<-c("estimate","se_kyoku","stat_kyoku","p_kyoku");b<-tryCatch(as.data.frame(coeftable(m,vcov=vcov_cluster(m,cluster=d$ka_norm)))%>%rownames_to_column("term"),error=function(x)NULL);if(is.null(b))a<-a%>%mutate(se_ka=NA_real_,p_ka=NA_real_)else{names(b)[2:5]<-c("e2","se_ka","s2","p_ka");a<-left_join(a,b%>%select(term,se_ka,p_ka),by="term")};ints<-intersect(c(ints,"Draft_ko:logStaff"),a$term);pw<-setNames(rep(NA_real_,nrow(a)),a$term);if(type=="ols")for(z in ints)pw[z]<-webbp(m,z);a%>%mutate(family=fam,outcome=y,spec,type,status="ok",n=nobs(m),clusters_kyoku=n_distinct(d$kyoku_fe),clusters_ka=n_distinct(d$ka_norm,na.rm=TRUE),p_webb=unname(pw[term]),diagnostic=paste(unique(warn),collapse=" | "))%>%select(family,outcome,spec,type,status,n,clusters_kyoku,clusters_ka,term,estimate,se_kyoku,p_kyoku,se_ka,p_ka,p_webb,diagnostic)}
runfam<-function(ys,pools,fam)bind_rows(map_dfr(ys,~fit(p,.x,pools,fam,"main")),map_dfr(ys,~fit(p,.x,pools,fam,"ppml","ppml")),map_dfr(ys,~fit(filter(p,Staff_ko>=3),.x,pools,fam,"staff_ge_3")),map_dfr(ys,~fit(filter(p,observed_ka),.x,pools,fam,"observed_ka")),map_dfr(ys,~fit(filter(p,high_link_kyoku),.x,pools,fam,"high_link_kyoku")))
lo<-paste0("lateral_",ld);po<-paste0("promotion_",prd);lr<-runfam(lo,lv,"lateral");pr<-bind_rows(runfam(po,pv,"promotion"),map_dfr(po,~fit(p,.x,pnv,"promotion","ignore_track")));nr<-runfam("new_hires",c(lv,pv),"new_hires")
write_csv(lr,file.path(tab,"regression_lateral.csv"));write_csv(pr,file.path(tab,"regression_promotion.csv"));write_csv(nr,file.path(tab,"regression_new_hires.csv"))
esc<-function(x)str_replace_all(x,"_","\\\\_")
tex<-function(r,path,cap,ys){z<-r%>%filter(spec=="main",type=="ols",status=="ok",str_starts(term,"Draft_ko:"));body<-map_chr(unique(z$term),~{q<-z%>%filter(term==.x)%>%right_join(tibble(outcome=ys),by="outcome");paste0(esc(.x)," & ",paste(map2_chr(q$estimate,q$p_webb,~ifelse(is.na(.x),"--",sprintf("%.3f [%.3f]",.x,.y))),collapse=" & ")," \\\\")});writeLines(c("\\begin{table}[!htbp]","\\centering",paste0("\\caption{",cap,"}"),paste0("\\begin{tabular}{l",paste(rep("c",length(ys)),collapse=""),"}"),"\\toprule",paste0("Interaction & ",paste(esc(ys),collapse=" & ")," \\\\"),"\\midrule",body,"\\bottomrule","\\end{tabular}","\\footnotesize OLS coefficients; Webb wild-cluster p-values (9,999 draws) in brackets.","\\end{table}"),path,useBytes=TRUE)}
tex(lr,file.path(tab,"regression_lateral.tex"),"Lateral arrivals",lo);tex(pr,file.path(tab,"regression_promotion.tex"),"Promotion arrivals",po);tex(nr,file.path(tab,"regression_new_hires.tex"),"New hires","new_hires")
ss<-tibble(statistic=c("1944 male cells","1944 eligible male workers","Drafted men","Drafted women excluded","Linked eligible men","Incumbents","Cells Staff below 3","Kyoku clusters","Ka clusters"),value=c(nrow(p),nrow(w44),sum(w44$drafted%in%TRUE),nrow(dw),length(linked),nrow(inc),sum(p$Staff_ko<3),n_distinct(p$kyoku_fe),n_distinct(p$ka_norm,na.rm=TRUE)));write_csv(ss,file.path(tab,"summary_statistics.csv"));writeLines(c("\\begin{tabular}{lr}","\\toprule","Statistic & Value \\\\","\\midrule",paste0(esc(ss$statistic)," & ",ss$value," \\\\"),"\\bottomrule","\\end{tabular}"),file.path(tab,"summary_statistics.tex"),useBytes=TRUE)
